; Conceit: VEX variant of Covetous for CellHack2.  GENERATED by cells/gen_conceit.py -- do not edit by hand.
; Written with AI help.
;
; Paste this whole file into the site.  It has no org/bits/section/%include on purpose: the server
; prepends `bits 64 / org CODE_BASE / default rel / <cellhack.inc>` and runs `nasm -f bin`.
; CPU target: the site's qemu CPU: SSE2 plus AVX-128 VEX forms of SSE2 ops (vpcmpeqb, site-verified with an
; unaligned memory operand).  No SSSE3/SSE4/BMI/popcnt/ymm.  No legacy-SSE memory operand, so no alignment
; rule.  No memory writes, no loops, no stack use.
; Relies on: rax = 0 at entry (registers are reset before every call).  The bite path leaves with
; `jnz EXIT_ADDR` (a jump to the address `ret` would return to) instead of `ret`.
;
; Behaviour: exactly Covetous's (cells/covetous.asm).
;   1. An enemy next to me: bite it.  One enemy: that one.  Two or four: first of DOWN, LEFT, UP, RIGHT.
;      Exactly three: the one opposite the single non-enemy side.  (Same choices as Sprint.)
;   2. Otherwise split when energy >= threshold.  Threshold = 5, but 16 while an enemy is anywhere
;      in the 5x5 view, and 5 again from tick 2980 on.  The split goes to the first empty adjacent
;      square of DOWN, RIGHT, UP, LEFT.
;   3. When not splitting (no empty neighbour, or holding for the threshold) and energy >= 47: feed the
;      poorest friend neighbour (ties UP, RIGHT, DOWN, LEFT) if its energy <= 46.
;   4. Otherwise rest.
;
; Instruction counts per path (every executed instruction, including taken jumps and ret;
; in brackets the same path with taken jumps not counted); Covetous's minus 1 on every path through the
; split check (the bite's raw window is compared again instead of reloaded):
;   bite (any adjacent enemy)                                     5  (4)
;   rest, e < 5                                                9  (8)
;   split, no enemy in view, e >= 5                              21 (21)
;   split, enemy in view, e >= 16                                 23 (21)
;   split, enemy in view, 5 <= e < 16, tick >= 2980               25 (23)
;   feed block entered at F (F = 19 no enemy in view / no empty; 19 holding in view, tick < 2980;
;     21 enemy in view, e >= 16, no empty; 23 same but late with e < 16):
;     rest, e < 47                                               F + 4
;     otherwise F + 4 + sum over UP, RIGHT, DOWN, LEFT of: 2 not a friend / 5 friend, not poorer than
;     the poorest so far / 7 new poorest; then feed +3, rest (no friend, or poorest > 46) +4.
;     Longest: 23 + 4 + 28 + 4 = 59, far below INSN_BUDGET.

start:
	movdqu		xmm3, [rdi + VIEW_CELLS + VIEW_UP]	; raw view idx 7..22, kept for the split check
	vpcmpeqb	xmm0, xmm3, [kEnemy]
	pmovmskb	ecx, xmm0			; bits 0 UP, 4 LEFT, 6 RIGHT, 10 DOWN
	or		al, [abs bite_tbl + rcx]	; rax = 0 at entry: al = eat action, ZF = no enemy
	jnz		EXIT_ADDR			; bite: leave through the return address

slow:						; 5 instructions so far
	cmp		esi, SPLIT_MIN
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	vpcmpeqb	xmm1, xmm1, [kTwoLo]		; lane 12 (self) never matches
	vpcmpeqb	xmm2, xmm2, [kTwoHi]		; lane 3 (self) never matches
	por		xmm1, xmm2
	pmovmskb	eax, xmm1
	test		eax, eax
	jnz		threat
split:
	vpcmpeqb	xmm0, xmm3, [kEmpty]		; the bite's raw window again
	pmovmskb	eax, xmm0			; bits set = empty adjacent squares
	test		eax, eax
	jz		feed
	mov		al, [abs split_tbl + rax]	; non-zero mask -> a split
	ret
threat:
	cmp		esi, 16
	jae		split
	cmp		dword [rdi + VIEW_TICK], 2980
	jae		split
feed:
	cmp		esi, 47
	jb		rest
	mov		r8d, 255			; poorest friend energy so far
	mov		eax, ACT_REST
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND	; up
	jne		.n_up
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 7]
	cmp		ecx, r8d
	jae		.n_up
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_UP
.n_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND	; right
	jne		.n_right
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 13]
	cmp		ecx, r8d
	jae		.n_right
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_RIGHT
.n_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND	; down
	jne		.n_down
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 17]
	cmp		ecx, r8d
	jae		.n_down
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_DOWN
.n_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND	; left
	jne		.n_left
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 11]
	cmp		ecx, r8d
	jae		.n_left
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_LEFT
.n_left:
	cmp		r8d, 46
	ja		rest				; no friend (255), or the poorest is near the cap too
	ret					; al = ACT_FEED + direction
rest:
	mov		al, ACT_REST
	ret

; ---- constants (VEX memory operands: no alignment needed)
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes
kEmpty:	db 0x00, 0xff, 0xff, 0xff, 0x00, 0xff, 0x00, 0xff, 0xff, 0xff, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff	; 0 at UP/LEFT/RIGHT/DOWN lanes
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded

; ---- bite_tbl: 1106 bytes, index = adjacent-enemy mask; 0 = no enemy (falls to slow)
bite_tbl:

	times 1 db 0x00
	db 0x30		; mask 0x001
	times 14 db 0x00
	db 0x33		; mask 0x010
	db 0x33		; mask 0x011
	times 46 db 0x00
	db 0x31		; mask 0x040
	db 0x30		; mask 0x041
	times 14 db 0x00
	db 0x33		; mask 0x050
	db 0x30		; mask 0x051
	times 942 db 0x00
	db 0x32		; mask 0x400
	db 0x32		; mask 0x401
	times 14 db 0x00
	db 0x32		; mask 0x410
	db 0x33		; mask 0x411
	times 46 db 0x00
	db 0x32		; mask 0x440
	db 0x31		; mask 0x441
	times 14 db 0x00
	db 0x32		; mask 0x450
	db 0x32		; mask 0x451
bite_tbl_end:

; ---- split_tbl: 1106 bytes, index = empty-adjacent mask (mask 0 never looked up)
split_tbl:
	db 0x01		; mask 0x000
	db 0x20		; mask 0x001
	times 14 db 0x01
	db 0x23		; mask 0x010
	db 0x20		; mask 0x011
	times 46 db 0x01
	db 0x21		; mask 0x040
	db 0x21		; mask 0x041
	times 14 db 0x01
	db 0x21		; mask 0x050
	db 0x21		; mask 0x051
	times 942 db 0x01
	db 0x22		; mask 0x400
	db 0x22		; mask 0x401
	times 14 db 0x01
	db 0x22		; mask 0x410
	db 0x22		; mask 0x411
	times 46 db 0x01
	db 0x22		; mask 0x440
	db 0x22		; mask 0x441
	times 14 db 0x01
	db 0x22		; mask 0x450
	db 0x22		; mask 0x451
split_tbl_end:
